//! `M5-06` — publish the pre-built example bundles next to the documentation.
//!
//! `examples/gallery/src/web/fw/<framework>/` already holds the *committed* static output of the
//! nine framework demos (they are regenerated by `node scripts/gen-framework-demos.mjs`, never by
//! CI). The gallery serves them from the root of a custom scheme (`tauri://localhost/fw/react/`),
//! so their asset URLs are absolute (`/assets/…`, `/_next/…`, `/zts/fonts/…`).
//!
//! GitHub Pages serves this site from a sub-path (`/Z-Ts/`), so absolute URLs would escape the
//! repository and 404. [`rewriteAbsoluteUrls`] rewrites them to be relative to the demo directory —
//! the fonts move up one level (`../fonts/`) because all nine demos share a single copy.
//!
//! The rewrite is a pure function of the text and is unit-tested; [`copyDemo`] only does IO.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

/// `std.Io.Writer.Allocating` reports allocation failure as `error.WriteFailed` (same convention as
/// `markdown.zig` / `site.zig`).
const Error = Allocator.Error || error{WriteFailed};

pub const RewriteOptions = struct {
    /// Where `/zts/fonts/…` should point from the file being rewritten.
    font_prefix: []const u8 = "../fonts/",
    /// The prefix the gallery uses for fonts.
    font_source: []const u8 = "/zts/fonts/",
    /// `../` repeated for files that live below the demo root (Next.js writes `404/index.html`).
    asset_prefix: []const u8 = "",
};

/// Makes every asset URL in `text` relative to the page's own directory.
///
/// * `href="/"` → `href="./"` (a bare root link would leave the site)
/// * `src="/assets/app.js"` → `src="assets/app.js"`
/// * `"_next/static/…"` inside a JS chunk → `"_next/static/…"`
/// * `url(/zts/fonts/x.woff2)` → `url(../fonts/x.woff2)`
/// * protocol-relative (`//host/…`) and absolute (`https://…`) URLs are left alone.
pub fn rewriteAbsoluteUrls(arena: Allocator, text: []const u8, options: RewriteOptions) Error![]const u8 {
    var out: std.Io.Writer.Allocating = .init(arena);
    defer out.deinit();
    const writer = &out.writer;

    var i: usize = 0;
    while (i < text.len) {
        // 1. The shared font directory.
        if (options.font_source.len > 0 and std.mem.startsWith(u8, text[i..], options.font_source)) {
            writer.writeAll(options.font_prefix) catch return error.OutOfMemory;
            i += options.font_source.len;
            continue;
        }

        // 2. `href="/"` would navigate to the domain root; keep it inside the demo.
        if (std.mem.startsWith(u8, text[i..], "href=\"/\"")) {
            writer.writeAll("href=\"") catch return error.OutOfMemory;
            writer.writeAll(if (options.asset_prefix.len == 0) "./" else options.asset_prefix) catch return error.OutOfMemory;
            writer.writeAll("\"") catch return error.OutOfMemory;
            i += "href=\"/\"".len;
            continue;
        }

        // 3. Any quoted/parenthesised absolute path (`="/…`, `:"/…`, `url(/…`) loses its leading
        //    slash, unless it is protocol-relative (`//host/…`).
        const opener = openerAt(text[i..]);
        if (opener) |prefix_len| {
            const offset: usize = prefix_len;
            const slash_at = i + offset;
            const next = if (slash_at + 1 < text.len) text[slash_at + 1] else 0;
            if (next != '/') {
                writer.writeAll(text[i..slash_at]) catch return error.OutOfMemory;
                // `/zts/fonts/…` lives one directory up; other prefixes just lose their slash.
                const after = text[slash_at + 1 ..];
                if (options.font_source.len > 1 and std.mem.startsWith(u8, after, options.font_source[1..])) {
                    writer.writeAll(options.font_prefix) catch return error.OutOfMemory;
                    i = slash_at + 1 + options.font_source.len - 1;
                } else {
                    // Keep the file's own depth: `dist/404/index.html` needs `../assets/…`.
                    writer.writeAll(options.asset_prefix) catch return error.OutOfMemory;
                    i = slash_at + 1;
                }
                continue;
            }
        }

        writer.writeByte(text[i]) catch return error.OutOfMemory;
        i += 1;
    }

    return out.toOwnedSlice();
}

/// Length of the opener (`="`, `:'`, `:"`, `url(`, `url('`, `url("`) when `rest` starts with one
/// followed by a `/`.
fn openerAt(rest: []const u8) ?usize {
    const openers = [_][]const u8{ "=\"/", "='/", ":\"/", ":'/", "url(/", "url('/", "url(\"/" };
    for (openers) |opener| {
        if (std.mem.startsWith(u8, rest, opener)) return opener.len - 1; // index of the slash
    }
    return null;
}

pub const CopyResult = struct {
    files: usize = 0,
    bytes: usize = 0,
};

/// Copies one demo directory (`src_path`) into `<dst_prefix><name>/`, rewriting its text files.
pub fn copyDemo(
    arena: Allocator,
    io: Io,
    src_path: []const u8,
    name: []const u8,
    out_dir: Io.Dir,
    dst_prefix: []const u8,
    options: RewriteOptions,
) !CopyResult {
    const cwd = Io.Dir.cwd();
    const src_dir = try cwd.openDir(io, src_path, .{ .iterate = true });
    defer src_dir.close(io);

    var result: CopyResult = .{};
    var walker = try src_dir.walk(arena);
    defer walker.deinit();

    while (try walker.next(io)) |entry| {
        if (entry.kind != .file) continue;

        const bytes = try src_dir.readFileAlloc(io, entry.path, arena, .limited(32 * 1024 * 1024));
        const target = try std.fmt.allocPrint(arena, "{s}{s}/{s}", .{ dst_prefix, name, entry.path });

        if (isTextAsset(entry.path)) {
            var depth: usize = 0;
            for (entry.path) |ch| if (ch == '/') {
                depth += 1;
            };
            const up = try arena.alloc(u8, depth * 3);
            for (0..depth) |index| @memcpy(up[index * 3 ..][0..3], "../");
            const font_up = try arena.alloc(u8, (depth + 1) * 3);
            for (0..depth + 1) |index| @memcpy(font_up[index * 3 ..][0..3], "../");
            const rewritten = try rewriteAbsoluteUrls(arena, bytes, .{
                .font_prefix = try std.fmt.allocPrint(arena, "{s}fonts/", .{font_up}),
                .font_source = options.font_source,
                .asset_prefix = up,
            });
            try writeFileIn(out_dir, io, target, rewritten);
            result.bytes += rewritten.len;
        } else {
            try writeFileIn(out_dir, io, target, bytes);
            result.bytes += bytes.len;
        }
        result.files += 1;
    }
    return result;
}

/// Copies the shared font files (and nothing else) into `<dst_prefix>fonts/`.
pub fn copyFonts(
    arena: Allocator,
    io: Io,
    src_path: []const u8,
    out_dir: Io.Dir,
    dst_prefix: []const u8,
) !CopyResult {
    const cwd = Io.Dir.cwd();
    const src_dir = try cwd.openDir(io, src_path, .{ .iterate = true });
    defer src_dir.close(io);

    var result: CopyResult = .{};
    var walker = try src_dir.walk(arena);
    defer walker.deinit();

    while (try walker.next(io)) |entry| {
        if (entry.kind != .file) continue;
        if (!std.mem.endsWith(u8, entry.path, ".woff2")) continue;

        const bytes = try src_dir.readFileAlloc(io, entry.path, arena, .limited(8 * 1024 * 1024));
        const target = try std.fmt.allocPrint(arena, "{s}fonts/{s}", .{ dst_prefix, entry.path });
        try writeFileIn(out_dir, io, target, bytes);
        result.files += 1;
        result.bytes += bytes.len;
    }
    return result;
}

fn isTextAsset(path: []const u8) bool {
    for ([_][]const u8{ ".html", ".css", ".js", ".mjs", ".json", ".svg", ".txt", ".map" }) |extension| {
        if (std.mem.endsWith(u8, path, extension)) return true;
    }
    return false;
}

fn writeFileIn(dir: Io.Dir, io: Io, sub_path: []const u8, data: []const u8) !void {
    if (std.mem.lastIndexOfScalar(u8, sub_path, '/')) |slash| {
        if (slash > 0) try dir.createDirPath(io, sub_path[0..slash]);
    }
    try dir.writeFile(io, .{ .sub_path = sub_path, .data = data });
}

/// The landing page of `examples/frameworks/`: one card per demo, every link opens a new tab so the
/// visitor does not lose the list.
pub fn renderIndex(arena: Allocator, names: []const []const u8) Error![]const u8 {
    var out: std.Io.Writer.Allocating = .init(arena);
    defer out.deinit();
    const w = &out.writer;

    try w.writeAll(
        \\<!doctype html>
        \\<html lang="ja" data-theme="light">
        \\<head>
        \\<meta charset="utf-8" />
        \\<meta name="viewport" content="width=device-width, initial-scale=1" />
        \\<title>フレームワーク別デモ — Z-Ts</title>
        \\<link rel="stylesheet" href="../../assets/site.css" />
        \\<script>try{const t=localStorage.getItem("zts-theme");if(t)document.documentElement.dataset.theme=t}catch(e){}</script>
        \\</head>
        \\<body class="landing">
        \\<header class="topbar">
        \\  <a class="brand" href="../../index.html"><span class="brand-mark">Z</span> Z-Ts <span class="brand-sub">Tauri in Zig</span></a>
        \\  <div class="topbar-actions"><a class="gh" href="../../index.html">Docs</a></div>
        \\</header>
        \\<main class="hero">
        \\  <p class="eyebrow">M5-05 / M5-06</p>
        \\  <h1>9 つのフレームワーク、<span class="accent">同じ 1 画面</span></h1>
        \\  <p class="lede">Angular / Solid / Svelte / SolidStart / Next.js / Nuxt / Astro / SvelteKit / React で
        \\  まったく同じダッシュボード風カウンターを作り、同梱フォントだけで描画しています。
        \\  どの実装も同じ Zig の <code>zts_webview</code> に載り、CI が 3 OS のスクリーンショットを相互比較します。</p>
        \\  <div class="cards">
        \\
    );

    for (names) |name| {
        try w.writeAll("<article><h2><a href=\"");
        try writeEscaped(w, name);
        try w.writeAll("/index.html\" target=\"_blank\" rel=\"noopener\">");
        try writeEscaped(w, displayName(name));
        try w.writeAll("</a></h2><p>");
        try writeEscaped(w, noteFor(name));
        try w.writeAll("</p></article>\n");
    }

    try w.writeAll(
        \\  </div>
        \\  <p class="lede" style="margin-top:2rem;font-size:.9rem">
        \\    静的出力はリポジトリにコミット済み（<code>node scripts/gen-framework-demos.mjs</code> で再生成）なので、
        \\    このページはビルドもネットワークも使わずに配信されます。
        \\  </p>
        \\</main>
        \\</body>
        \\</html>
        \\
    );
    return out.toOwnedSlice();
}

fn displayName(name: []const u8) []const u8 {
    for ([_][]const u8{ "angular", "solid", "svelte", "solidstart", "next", "nuxt", "astro", "sveltekit", "react" }) |known| {
        if (std.mem.eql(u8, name, known)) {
            return switch (name.len) {
                4 => "Next.js",
                9 => "SvelteKit",
                else => switch (name[0]) {
                    'a' => "Angular",
                    's' => if (std.mem.eql(u8, name, "solid")) "Solid" else if (std.mem.eql(u8, name, "svelte")) "Svelte" else "SolidStart",
                    'n' => "Nuxt",
                    'r' => "React",
                    else => name,
                },
            };
        }
    }
    return name;
}

fn noteFor(name: []const u8) []const u8 {
    if (std.mem.eql(u8, name, "angular")) return "ng build / @angular/build。index.html に script を書かない。";
    if (std.mem.eql(u8, name, "solid")) return "vite build。シグナルで状態を保持。";
    if (std.mem.eql(u8, name, "svelte")) return "vite build。Svelte 5 の mount() API。";
    if (std.mem.eql(u8, name, "solidstart")) return "vite build。SPA モードで index.html を生成。";
    if (std.mem.eql(u8, name, "next")) return "next build（output: 'export'）。静的書き出し。";
    if (std.mem.eql(u8, name, "nuxt")) return "nuxt generate。/_payload.json は 404 だが SSR 済み DOM で描画。";
    if (std.mem.eql(u8, name, "astro")) return "astro build。アイランドは使わず完全静的。";
    if (std.mem.eql(u8, name, "sveltekit")) return "vite build + adapter-static（prerender）。";
    if (std.mem.eql(u8, name, "react")) return "vite build。class → className の変換のみ。";
    return "";
}

fn writeEscaped(w: *std.Io.Writer, text: []const u8) !void {
    for (text) |ch| {
        switch (ch) {
            '<' => try w.writeAll("&lt;"),
            '>' => try w.writeAll("&gt;"),
            '&' => try w.writeAll("&amp;"),
            '"' => try w.writeAll("&quot;"),
            else => try w.writeByte(ch),
        }
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

const testing = std.testing;

fn rewriteForTest(arena: Allocator, text: []const u8) ![]const u8 {
    return rewriteAbsoluteUrls(arena, text, .{});
}

test "attribute URLs lose their leading slash" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    try testing.expectEqualStrings(
        "<script src=\"assets/index.js\" defer></script>",
        try rewriteForTest(arena, "<script src=\"/assets/index.js\" defer></script>"),
    );
    try testing.expectEqualStrings(
        "<link href=\"_next/static/a.css\" rel=\"stylesheet\">",
        try rewriteForTest(arena, "<link href=\"/_next/static/a.css\" rel=\"stylesheet\">"),
    );
}

test "the shared font directory points one level up" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    try testing.expectEqualStrings(
        "<style>@font-face{src:url(../fonts/zts-sans-400.woff2)format(\"woff2\")}</style>",
        try rewriteForTest(arena, "<style>@font-face{src:url(/zts/fonts/zts-sans-400.woff2)format(\"woff2\")}</style>"),
    );
}

test "a bare root link stays inside the demo directory" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    try testing.expectEqualStrings("<a href=\"./\">home</a>", try rewriteForTest(arena, "<a href=\"/\">home</a>"));
}

test "protocol-relative and absolute URLs are untouched" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const input = "<a href=\"//cdn.example.com/x.js\">a</a><img src=\"https://example.com/y.png\">";
    try testing.expectEqualStrings(input, try rewriteForTest(arena, input));
}

test "JS chunk public paths are rewritten too" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    try testing.expectEqualStrings(
        "const p=\"_next/\";fetch(\"/_payload.json\")",
        try rewriteForTest(arena, "const p=\"/_next/\";fetch(\"/_payload.json\")"),
    );
}

test "the `colon-slash` form used by bundlers is rewritten as well" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    try testing.expectEqualStrings(
        "t.PUBLIC_CHUNK_BASE_PATH:\"_next/\"",
        try rewriteForTest(arena, "t.PUBLIC_CHUNK_BASE_PATH:\"/_next/\""),
    );
    try testing.expectEqualStrings(
        "url('assets/a.woff2')",
        try rewriteForTest(arena, "url('/assets/a.woff2')"),
    );
}

test "files below the demo root keep their own depth" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const options: RewriteOptions = .{ .asset_prefix = "../", .font_prefix = "../../fonts/" };
    try testing.expectEqualStrings(
        "<link href=\"../_next/static/a.css\"><a href=\"../\">home</a>",
        try rewriteAbsoluteUrls(arena, "<link href=\"/_next/static/a.css\"><a href=\"/\">home</a>", options),
    );
    try testing.expectEqualStrings(
        "url(../../fonts/zts-sans-400.woff2)",
        try rewriteAbsoluteUrls(arena, "url(/zts/fonts/zts-sans-400.woff2)", options),
    );
}

test "rewriting is idempotent" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const once = try rewriteForTest(arena, "<img src=\"/assets/a.png\">");
    const twice = try rewriteForTest(arena, once);
    try testing.expectEqualStrings(once, twice);
}

test "renderIndex links every demo and needs no network" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const html = try renderIndex(arena, &.{ "react", "sveltekit", "next" });
    try testing.expect(std.mem.indexOf(u8, html, "href=\"react/index.html\"") != null);
    try testing.expect(std.mem.indexOf(u8, html, "SvelteKit") != null);
    try testing.expect(std.mem.indexOf(u8, html, "Next.js") != null);
    try testing.expect(std.mem.indexOf(u8, html, "http://") == null);
    try testing.expect(std.mem.indexOf(u8, html, "https://") == null);
}
